    .reg .s32   %r<64>;
    .reg .u64   %rd<32>;
    .reg .f32   %f<8>;

    // Load parameters
    ld.param.u64 %rd0, [input_ptr];    // input base
    ld.param.u64 %rd1, [weight_ptr];   // weight base
    ld.param.u64 %rd2, [bias_ptr];     // bias base
    ld.param.u64 %rd3, [output_ptr];   // output base

    // Thread index computation
    mov.u32 %r0, %tid.x;
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mad.lo.s32 %r3, %r1, %r2, %r0;     // linear thread id

    // Total outputs = 256 * 96 * 55 * 55 = 74342400
    mov.u32 %r4, 74342400;
    setp.ge.s32 %p0, %r3, %r4;
    @%p0 bra RET;

    // Constants
    mov.u32 %r5, 55;   // OW
    mov.u32 %r6, 55;   // OH
    mov.u32 %r7, 96;   // OC
    mov.u32 %r8, 224;  // H, W
    mov.u32 %r9, 224;  // W (same)
    mov.u32 %r10, 3;   // C
    mov.u32 %r11, 11;  // KH, KW

    // Decompose index into (n, oc, oh, ow)
    // ow = idx % 55; t1 = idx / 55;
    rem.u32 %r12, %r3, %r5;     // ow
    div.u32 %r13, %r3, %r5;     // t1
    // oh = t1 % 55; t2 = t1 / 55;
    rem.u32 %r14, %r13, %r6;    // oh
    div.u32 %r15, %r13, %r6;    // t2
    // oc = t2 % 96; n = t2 / 96;
    rem.u32 %r16, %r15, %r7;    // oc
    div.u32 %r17, %r15, %r7;    // n

    // Load bias[oc]
    mul.wide.u32 %rd10, %r16, 4;
    add.u64 %rd11, %rd2, %rd10;
    ld.global.f32 %f0, [%rd11]; // accumulator initialized with bias

    // base offsets for ih/iw computation
    // ih = oh*4 - 2 + kh; iw = ow*4 - 2 + kw
    mul.lo.s32 %r18, %r14, 4;   // oh*4
    mul.lo.s32 %r19, %r12, 4;   // ow*4
    add.s32 %r20, %r18, -2;     // base_ih
    add.s32 %r21, %r19, -2;     // base_iw

