    mov.u32 %r22, 0;            // ic = 0
IC_LOOP:
    setp.ge.u32 %p1, %r22, %r10;
    @%p1 bra IC_DONE;

    // kh loop
    mov.u32 %r23, 0;            // kh = 0
KH_LOOP:
    setp.ge.u32 %p2, %r23, %r11;
    @%p2 bra KH_DONE;

    add.s32 %r24, %r20, %r23;   // ih = base_ih + kh

    // kw loop
    mov.u32 %r25, 0;            // kw = 0
