    setp.lt.s32 %p4, %r24, 0;
    setp.ge.s32 %p5, %r24, %r8;
    or.pred %p6, %p4, %p5;
    setp.lt.s32 %p7, %r26, 0;
    setp.ge.s32 %p8, %r26, %r9;
    or.pred %p9, %p7, %p8;
    or.pred %p10, %p6, %p9;
    @%p10 bra SKIP_ACCUM;

