    mad.lo.s32 %r27, %r17, %r10, %r22;   // n*3 + ic
    mad.lo.s32 %r28, %r27, %r8,  %r24;   // *224 + ih
    mad.lo.s32 %r29, %r28, %r9,  %r26;   // *224 + iw
    mul.wide.u32 %rd12, %r29, 4;
    add.u64 %rd13, %rd0, %rd12;
    ld.global.f32 %f1, [%rd13];

    // weight index: (((oc*3 + ic)*11 + kh)*11 + kw)
    mad.lo.s32 %r30, %r16, %r10, %r22;   // oc*3 + ic
    mad.lo.s32 %r31, %r30, %r11, %r23;   // *11 + kh
    mad.lo.s32 %r32, %r31, %r11, %r25;   // *11 + kw
    mul.wide.u32 %rd14, %r32, 4;
    add.u64 %rd15, %rd1, %rd14;
    ld.global.f32 %f2, [%rd15];

