    mad.lo.s32 %r33, %r17, %r7, %r16;    // n*96 + oc
    mad.lo.s32 %r34, %r33, %r6, %r14;    // *55 + oh
    mad.lo.s32 %r35, %r34, %r5, %r12;    // *55 + ow
    mul.wide.u32 %rd16, %r35, 4;
    add.u64 %rd17, %rd3, %rd16;
    st.global.f32 [%rd17], %f0;

